:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  place-items: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 18px 18px 16px;
  display: grid;
  gap: 16px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.play,
.rate,
.lang,
.loop,
.back {
  border-radius: 10px;
  border: 1px solid #374151;
  background: #0f172a;
  color: #e5e7eb;
  padding: 8px 12px;
  font-size: 13px;
  cursor: pointer;
}

.play {
  min-width: 72px;
  border-color: #a3e635;
  background: #1a2e05;
}

.rate--active,
.loop--on {
  border-color: #a3e635;
  color: #a3e635;
}

.time,
.status {
  margin-left: auto;
  font-size: 12px;
  color: #9ca3af;
}

.field {
  display: grid;
  gap: 6px;
}

.label {
  font-size: 13px;
  color: #9ca3af;
}

.search {
  width: 100%;
  box-sizing: border-box;
  border-radius: 10px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 8px 12px;
  font-size: 14px;
  outline: none;
}

.search:focus {
  border-color: #a3e635;
  box-shadow: 0 0 0 1px #a3e63533;
}

.position {
  font-size: 12px;
  color: #6b7280;
}

.lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}

.line {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid #1f2937;
  background: #020617;
  font-size: 14px;
  color: #9ca3af;
}

.line--active {
  border-color: #a3e635;
  color: #e5e7eb;
  background: #0f172a;
}
